-- Keep privilege-bearing implementations outside the exposed API schema.
alter function public.imaging_register_source(uuid,text,boolean) set schema private;
create function public.imaging_register_source(p_center uuid,p_name text,p_auto_publish boolean default false) returns jsonb language sql security invoker set search_path='' as $$ select private.imaging_register_source(p_center,p_name,p_auto_publish); $$;
revoke all on function public.imaging_register_source(uuid,text,boolean),private.imaging_register_source(uuid,text,boolean) from public,anon,authenticated;
grant execute on function public.imaging_register_source(uuid,text,boolean),private.imaging_register_source(uuid,text,boolean) to authenticated;
alter function public.imaging_revoke_source(uuid) set schema private;
create function public.imaging_revoke_source(p_source uuid) returns void language sql security invoker set search_path='' as $$ select private.imaging_revoke_source(p_source); $$;
